// IDs aufteilen: erwartet "kacheln" als kommagetrennte Liste von timeBuzzer-Kachel-IDs.
const roh = String($input.first().json.kacheln || '');
const ids = Array.from(new Set(roh.split(',').map(function (x) { return x.trim(); }).filter(function (x) { return /^\d+$/.test(x); })));
if (!ids.length) throw new Error('TB 1: Keine Kachel-IDs übergeben – Prüfung abgebrochen.');
return ids.map(function (id) { return { json: { id: id } }; });

// Ergebnis: Status je Kachel. aktiv = vorhanden, archiviert = in timeBuzzer archiviert, geloescht = existiert nicht mehr (404).
// Jede andere Antwort bricht ab, damit kein Sync auf unsicherer Grundlage etwas aendert.
const ids = $('IDs aufteilen').all().map(function (i) { return i.json.id; });
const antworten = $input.all().map(function (i) { return i.json; });
if (antworten.length !== ids.length) throw new Error('TB 1: Antwortanzahl passt nicht (' + antworten.length + ' statt ' + ids.length + ').');
const status = {};
for (let k = 0; k < ids.length; k++) {
  const a = antworten[k] || {};
  const code = Number(a.statusCode);
  const body = a.body || {};
  if (code === 200 && String(body.id) === ids[k]) status[ids[k]] = body.archived ? 'archiviert' : 'aktiv';
  else if (code === 404) status[ids[k]] = 'geloescht';
  else throw new Error('TB 1: Unerwartete Antwort für Kachel ' + ids[k] + ' (HTTP ' + (a.statusCode || 'ohne Status') + ').');
}
return [{ json: { status: status, anzahl: ids.length } }];
